const KEYGEN_B64 = '';
const TICKET_B64 = '';

const KEYGEN_BUF = Buffer.from(KEYGEN_B64, 'base64');
const TICKET_BUF = Buffer.from(TICKET_B64, 'base64');
const KEYGEN_MODULE = new WebAssembly.Module(KEYGEN_BUF);
