function runKeygen(state) {
  const values = {
    'cctvh5openapi.state.guid': state.guid,
    'cctvh5openapi.state.yspappid': state.yspappid,
    'cctvh5openapi.state.version': state.version,
    'window.location.host': state.host,
    'window.location.protocol': state.protocol,
    'cctvh5openapi.state.token': state.token,
    'cctvh5openapi.state.input': state.input,
    'cctvh5openapi.state.ts': state.ts
  };
  const heap = new Array(132).fill(null);
  heap[129] = 'null';
  heap[130] = 'true';
  heap[131] = 'false';

  let wasmInstance;
  const imports = {
    wbg: {
      __wbg_get_9c1840f7ecd81363: (ptr, len) => {
        const u8 = new Uint8Array(wasmInstance.exports.memory.buffer);
        const key = Buffer.from(u8.subarray(ptr, ptr + len)).toString('utf8');
        const val = values[key] || '';
        heap.push(val);
        return heap.length - 1;
      },
      __wbindgen_string_get: (out_ptr, obj_idx) => {
        const val = heap[obj_idx];
        let ptr = 0, len = 0;
        if (typeof val === 'string') {
          const b = Buffer.from(val, 'utf8');
          ptr = wasmInstance.exports.__wbindgen_malloc(b.length, 1);
          new Uint8Array(wasmInstance.exports.memory.buffer).set(b, ptr);
          len = b.length;
        }
        const i32 = new Int32Array(wasmInstance.exports.memory.buffer);
        i32[out_ptr >> 2] = ptr;
        i32[(out_ptr >> 2) + 1] = len;
      },
      __wbindgen_object_drop_ref: (idx) => {
        if (idx >= 132) heap[idx] = null;
      }
    }
  };

  wasmInstance = new WebAssembly.Instance(KEYGEN_MODULE, imports);

  function callStringExport(fn) {
    const retPtr = wasmInstance.exports.__wbindgen_add_to_stack_pointer(-16);
    fn(retPtr);
    const i32 = new Int32Array(wasmInstance.exports.memory.buffer);
    const ptr = i32[retPtr >> 2];
    const len = i32[(retPtr >> 2) + 1];
    const u8 = new Uint8Array(wasmInstance.exports.memory.buffer);
    const str = Buffer.from(u8.subarray(ptr, ptr + len)).toString('utf8');
    wasmInstance.exports.__wbindgen_add_to_stack_pointer(16);
    if (ptr > 0 && len >= 0) wasmInstance.exports.__wbindgen_free(ptr, len, 1);
    return str;
  }

  return {
    getRnd: () => callStringExport(wasmInstance.exports.get_token_rnd),
    getSign: () => callStringExport(wasmInstance.exports.get_signature)
  };
}

